// The lazy modules must return exactly what the existing API returns, for every country.
// Needs the files generated by `npm run build` (CI builds before testing).
import { execFileSync } from 'child_process';
import path from 'path';
import { Country, State, City } from '../index';
import { getCountries, loadStatesOfCountry, loadCitiesOfState, loadCitiesOfCountry } from '../lazy';
import * as geo from '../lazy-geo';
import { ICity } from '../interface';

const countryCodes = Country.getAllCountries().map((c) => {
	return c.isoCode;
});
const withoutCoordinates = (cities: ICity[]) => {
	return cities.map(({ name, countryCode, stateCode }) => {
		return { name, countryCode, stateCode };
	});
};

describe('lib/lazy', () => {
	test('getCountries matches Country.getAllCountries, in the same order', () => {
		expect(getCountries()).toEqual(
			Country.getAllCountries().map(({ name, isoCode }) => {
				return { name, isoCode };
			}),
		);
	});

	test('loadStatesOfCountry matches State.getStatesOfCountry for every country', async () => {
		const lazy = await Promise.all(countryCodes.map(loadStatesOfCountry));
		countryCodes.forEach((code, i) => {
			const expected = State.getStatesOfCountry(code).map(({ name, isoCode, countryCode }) => {
				return { name, isoCode, countryCode };
			});
			expect(lazy[i]).toEqual(expected);
		});
	});

	test('loadCitiesOfCountry matches City.getCitiesOfCountry for every country, in the same order', async () => {
		const lazy = await Promise.all(countryCodes.map(loadCitiesOfCountry));
		countryCodes.forEach((code, i) => {
			expect(lazy[i]).toEqual(withoutCoordinates(City.getCitiesOfCountry(code) || []));
		});
	});

	test('loadCitiesOfState matches City.getCitiesOfState for every state, in the same order', async () => {
		const states = State.getAllStates();
		const lazy = await Promise.all(
			states.map((s) => {
				return loadCitiesOfState(s.countryCode, s.isoCode);
			}),
		);
		states.forEach((s, i) => {
			expect(lazy[i]).toEqual(withoutCoordinates(City.getCitiesOfState(s.countryCode, s.isoCode)));
		});
	});

	test('unknown or empty input resolves to []', async () => {
		expect(await loadStatesOfCountry('ZZ')).toEqual([]);
		expect(await loadStatesOfCountry('')).toEqual([]);
		expect(await loadCitiesOfState('ZZ', 'X')).toEqual([]);
		expect(await loadCitiesOfState('US', '')).toEqual([]);
		expect(await loadCitiesOfState('US', 'ZZ')).toEqual([]);
		expect(await loadCitiesOfCountry('constructor')).toEqual([]);
		expect(await loadCitiesOfCountry('__proto__')).toEqual([]);
	});

	test('changing a returned list does not affect later calls', async () => {
		(await loadCitiesOfState('IN', 'DL')).reverse();
		(await loadStatesOfCountry('IN')).pop();
		expect(await loadCitiesOfState('IN', 'DL')).toEqual(withoutCoordinates(City.getCitiesOfState('IN', 'DL')));
		expect((await loadStatesOfCountry('IN')).length).toBe(State.getStatesOfCountry('IN').length);
	});
});

describe('lib/lazy-geo', () => {
	test('loadCitiesOfCountry matches City.getCitiesOfCountry, coordinates included', async () => {
		const lazy = await Promise.all(countryCodes.map(geo.loadCitiesOfCountry));
		countryCodes.forEach((code, i) => {
			expect(lazy[i]).toEqual(City.getCitiesOfCountry(code) || []);
		});
	});

	test('loadCitiesOfState matches City.getCitiesOfState, coordinates included', async () => {
		expect(await geo.loadCitiesOfState('IN', 'KA')).toEqual(City.getCitiesOfState('IN', 'KA'));
		expect(await geo.loadCitiesOfState('US', 'CA')).toEqual(City.getCitiesOfState('US', 'CA'));
		expect(await geo.loadCitiesOfState('ZZ', 'X')).toEqual([]);
	});
});

describe('built CommonJS output', () => {
	// The CommonJS loaders read the per-country files from lib/assets (see shareLazyAssets.ts).
	test('lib/cjs/lazy and lib/cjs/lazy-geo load per-country files', () => {
		const lib = path.resolve(__dirname, '../../lib/cjs');
		const script = `
			const lazy = require(${JSON.stringify(path.join(lib, 'lazy'))});
			const geo = require(${JSON.stringify(path.join(lib, 'lazy-geo'))});
			Promise.all([lazy.loadStatesOfCountry('IN'), lazy.loadCitiesOfState('IN', 'KA'), geo.loadCitiesOfState('IN', 'KA')])
				.then(([states, cities, geoCities]) => {
					console.log(JSON.stringify([states.length, cities.length, geoCities[0], Object.keys(require.cache).some((f) => f.endsWith('city.json'))]));
				});
		`;
		const [states, cities, firstGeoCity, loadedCityList] = JSON.parse(
			execFileSync(process.execPath, ['-e', script], { encoding: 'utf-8' }),
		);
		expect(states).toBe(State.getStatesOfCountry('IN').length);
		expect(cities).toBe(City.getCitiesOfState('IN', 'KA').length);
		expect(firstGeoCity).toEqual(City.getCitiesOfState('IN', 'KA')[0]);
		expect(loadedCityList).toBe(false);
	});
});
